def f(g, mode='edge'):
    g=[r[:] for r in g]; h=len(g); w=len(g[0])
    cnt=Counter(v for r in g for v in r)
    bkg=cnt.most_common(1)[0][0]
    # seeds: colors forming small scattered objects; walls: large connected comps; choose by comp sizes
    vis=[[False]*w for _ in range(h)]; comps=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bkg and not vis[r][c]:
                q=deque([(r,c)]); vis[r][c]=True; comp=[]
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not vis[ny][nx] and g[ny][nx]!=bkg:
                            vis[ny][nx]=True; q.append((ny,nx))
                comps.append(comp)
    comps.sort(key=len)
    seeds=comps[0]  # smallest comp(s)
    wall=comps[-1]  # largest comp(s) - use all largest?
    seedcol=g[seeds[0][0]][seeds[0][1]]
    res=[r[:] for r in g]
    def fill(y,x,dx,dy):
        y+=dy; x+=dx
        while 0<=y<h and 0<=x<w and res[y][x]==bkg:
            res[y][x]=seedcol; y+=dy; x+=dx
    for s in seeds:
        sy,sx=s
        # 4-dir emission until blocked
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            fill(sy,sx,dx,dy)
        res[sy][sx]=4
    for comp in wall:
        rs=[y for y,x in comp]; cs=[x for y,x in comp]
        # orientation
        tall = (rs[-1]-rs[0]) >= (cs[-1]-cs[0])
        if mode=='edge':
            # emit perpendicular away from nearest edge
            if not tall:  # horizontal bar -> vertical rays
                if rs[0]==0: dr=1
                elif rs[-1]==h-1: dr=-1
                else: dr=None
                if dr is None: continue
                for (y,x) in comp:
                    fill(y,x,0,dr)
            else:  # vertical bar -> horizontal rays
                if cs[0]==0: dc=1
                elif cs[-1]==w-1: dc=-1
                else: dc=None
                if dc is None: continue
                for (y,x) in comp:
                    fill(y,x,dc,0)
        else:
            # toward nearest seed? skip
            pass
    return res
