    g=[r[:] for r in g]; h=len(g); w=len(g[0])
    cnt=Counter(v for r in g for v in r)
    bkg=cnt.most_common(1)[0][0]
    vis=[[False]*w for _ in range(h)]; comps=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bkg and not vis[r][c]:
                q=deque([(r,c)]); vis[r][c]=True; comp=[]
                while q:
                    p=q.popleft(); comp.append(p)
                    y,x=p
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not vis[ny][nx] and g[ny][nx]!=bkg:
                            vis[ny][nx]=True; q.append((ny,nx))
                comps.append(comp)
    comps.sort(key=len)
    seeds=comps[0]
    wall=comps[-1]
    seedcol=g[seeds[0][0]][seeds[0][1]]
    res=[r[:] for r in g]
    def fill(y,x,dc,dr):
        while True:
            y+=dr; x+=dc
            if not (0<=y<h and 0<=x<w) or res[y][x]!=bkg:
                break
            res[y][x]=seedcol
    for s in seeds:
        sy,sx=s
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            fill(sy,sx,dc,dr)
        res[sy][sx]=4
    for comp in wall:
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        rr=min(rs);rr2=max(rs); cc2=min(cs);cc3=max(cs)
        tall=(rr2-rr)>=(cc3-cc2)
        if not tall:
            # vertical bar: horizontal rays away from nearest edge
            if min(cs)==0: dc=1
            elif max(cs)==w-1: dc=-1
            else: continue
            for (y,x) in comp:
                fill(y,x,dc,0)
        else:
            if min(rs)==0: dr=1
            elif max(rs)==h-1: dr=-1
            else: continue
            for (y,x) in comp:
                fill(y,x,0,dr)
    return res
